function genTempPassword() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789";
  let out = "";
  for (let i = 0; i < 8; i++) out += chars[Math.floor(Math.random() * chars.length)];
  return out + "!1";
}

function genResetCode() {
  return String(Math.floor(100000 + Math.random() * 900000));
}

function buildMailto(to, subject, body) {
  return `mailto:${to}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

function makeNotification(to, subject) {
  return { id: "ntf_" + Date.now() + "_" + Math.random().toString(36).slice(2, 7), to, subject, timestamp: Date.now() };
}

function genId(prefix) {
  return prefix + "_" + Date.now() + "_" + Math.random().toString(36).slice(2, 9);
}

// --- Password hashing (client-side SHA-256 + per-user salt) ---------------
// This is meaningfully better than storing plaintext passwords, but it is
// NOT a substitute for real backend auth. A browser can only ever hash
// client-side with a fast, general-purpose digest (SHA-256) — real systems
// use a slow, purpose-built hash (bcrypt/scrypt/argon2) computed on a server
// the attacker never has code-level access to. Anyone who can read this
// file can see exactly how the hash is built, so an offline attacker who
// gets the stored {salt, passwordHash} pairs can still brute-force weak
// passwords quickly. Treat this as "no plaintext at rest in the demo",
// not as production-grade authentication.
async function sha256Hex(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
function genSalt() {
  const arr = crypto.getRandomValues(new Uint8Array(16));
  return Array.from(arr).map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function hashPassword(password, salt) {
  return sha256Hex(`${salt}:${password}`);
}
async function buildSeedUsers() {
  return Promise.all(
    SEED_USERS.map(async (u) => {
      const salt = genSalt();
      const passwordHash = await hashPassword(u.password, salt);
      const { password, ...rest } = u;
      return { ...rest, salt, passwordHash };
    })
  );
}

// An earlier version of this app stored plaintext {password} instead of {salt, passwordHash}.
// If that old shape is still sitting in window.storage from a previous run, login would
// otherwise fail forever comparing a fresh hash against an undefined passwordHash. Upgrade
// any such record in place, once, the next time the accounts list loads.
async function migrateUsers(list) {
  return Promise.all(
    list.map(async (u) => {
      if (u.salt && u.passwordHash) return u; // already on the new format
      const salt = genSalt();
      const passwordHash = await hashPassword(u.password || genTempPassword(), salt);
      const { password, ...rest } = u;
      return { ...rest, salt, passwordHash };
    })
  );
}

// --- File attachments -------------------------------------------------------
// window.storage only holds text/JSON, so a file's base64 content is stored
// under its own key (kept out of the main requests list) and only the small
// {key, name, type, size} pointer travels with the request/vendor record.
const MAX_ATTACHMENT_BYTES = 3 * 1024 * 1024; // ~3MB raw; base64 adds ~37%, storage caps a value at 5MB

function readFileAsDataURL(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(file);
  });
}

function formatBytes(bytes) {
  if (!bytes) return "0 KB";
  const kb = bytes / 1024;
  if (kb < 1024) return `${kb.toFixed(0)} KB`;
  return `${(kb / 1024).toFixed(1)} MB`;
}

