function LoginScreen({ users, onLoginSuccess, onResetPassword }) {
  const [mode, setMode] = useState("login"); // login | forgot | reset-sent
  const [employeeId, setEmployeeId] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const [forgotId, setForgotId] = useState("");
  const [resetCode, setResetCode] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [pendingReset, setPendingReset] = useState(null); // { user, code }
  const [forgotError, setForgotError] = useState("");
  const [resetDone, setResetDone] = useState(false);

  async function handleLogin(idOverride, passwordOverride) {
    const idToUse = idOverride !== undefined ? idOverride : employeeId;
    const pwToUse = passwordOverride !== undefined ? passwordOverride : password;
    const user = users.find((u) => u.employeeId.toLowerCase() === idToUse.trim().toLowerCase());
    if (!user) {
      setError("Incorrect employee ID or password.");
      return;
    }
    let attemptedHash;
    try {
      attemptedHash = await hashPassword(pwToUse, user.salt);
    } catch (e) {
      console.error("Password check failed", e);
      setError("Couldn't verify your password right now. Please refresh and try again.");
      return;
    }
    if (attemptedHash !== user.passwordHash) {
      setError("Incorrect employee ID or password.");
      return;
    }
    if (!user.active) {
      setError("This account has been deactivated. Contact your admin.");
      return;
    }
    setError("");
    onLoginSuccess(user);
  }

  function handleRequestReset() {
    const user = users.find((u) => u.employeeId.toLowerCase() === forgotId.trim().toLowerCase());
    if (!user) {
      setForgotError("No account found with that employee ID.");
      return;
    }
    setForgotError("");
    const code = genResetCode();
    setPendingReset({ user, code });
    window.open(
      buildMailto(
        user.email,
        "Password reset code — Oleevia DocFlow",
        `Hello ${user.name},\n\nYour password reset code is: ${code}\n\nEnter this code in Oleevia DocFlow to set a new password. If you did not request this, ignore this email.`
      ),
      "_blank"
    );
  }

  function handleConfirmReset() {
    if (!pendingReset) return;
    if (resetCode.trim() !== pendingReset.code) {
      setForgotError("That code doesn't match. Check the email and try again.");
      return;
    }
    if (newPassword.trim().length < 6) {
      setForgotError("New password must be at least 6 characters.");
      return;
    }
    onResetPassword(pendingReset.user.employeeId, newPassword.trim());
    setResetDone(true);
    setForgotError("");
  }

  function handleQuickLogin(acc) {
    setEmployeeId(acc.employeeId);
    setPassword(acc.password);
    handleLogin(acc.employeeId, acc.password);
  }

  return (
    <div className="w-full h-screen bg-neutral-50 flex items-center justify-center overflow-y-auto py-8" style={{ fontFamily: "system-ui, -apple-system, sans-serif" }}>
      <div className="w-full max-w-sm px-4">
        <div className="flex items-center justify-center mb-1">
          <img src={OLEEVIA_LOGO} alt="Oleevia" className="h-12 w-auto" />
        </div>
        <p className="text-[11px] text-neutral-400 text-center mb-5 tracking-wide">DOCFLOW</p>

        {mode === "login" && (
          <>
            <p className="text-xs text-neutral-400 text-center mb-6">Sign in with your employee ID</p>
            <div className="bg-white border border-neutral-200 rounded-xl p-5 space-y-3">
              <div>
                <label className="text-xs text-neutral-500 mb-1 block">Employee ID</label>
                <input
                  value={employeeId}
                  onChange={(e) => setEmployeeId(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleLogin()}
                  placeholder="e.g. OGC111"
                  className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100 focus:border-emerald-400"
                />
              </div>
              <div>
                <label className="text-xs text-neutral-500 mb-1 block">Password</label>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleLogin()}
                  placeholder="••••••••"
                  className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100 focus:border-emerald-400"
                />
              </div>
              {error && <p className="text-xs text-red-600">{error}</p>}
              <button onClick={() => handleLogin()} className="w-full bg-emerald-700 text-white text-sm font-medium py-2.5 rounded-lg hover:bg-emerald-800">
                Sign in
              </button>
              <button onClick={() => { setMode("forgot"); setForgotError(""); setPendingReset(null); setResetDone(false); }} className="w-full text-xs text-neutral-500 hover:text-emerald-700 text-center pt-1">
                Forgot password?
              </button>
            </div>
            <div className="mt-5">
              <div className="flex items-center gap-2 mb-2.5">
                <div className="h-px flex-1 bg-neutral-200" />
                <p className="text-[11px] text-neutral-400 whitespace-nowrap">Quick demo sign-in</p>
                <div className="h-px flex-1 bg-neutral-200" />
              </div>
              <div className="grid grid-cols-2 gap-2">
                {QUICK_LOGIN_ACCOUNTS.map((acc) => (
                  <button
                    key={acc.employeeId}
                    onClick={() => handleQuickLogin(acc)}
                    className="text-left bg-white border border-neutral-200 rounded-lg px-3 py-2.5 hover:border-emerald-300 hover:bg-emerald-50/50 transition-colors group"
                  >
                    <p className="text-xs font-medium text-neutral-800 group-hover:text-emerald-800">Sign in as {acc.roleLabel}</p>
                    <p className="text-[11px] text-neutral-400 mt-0.5 leading-snug">{acc.desc}</p>
                    <p className="text-[10px] text-neutral-300 font-mono mt-1">{acc.employeeId}</p>
                  </button>
                ))}
              </div>
            </div>
          </>
        )}

        {mode === "forgot" && !resetDone && (
          <div className="bg-white border border-neutral-200 rounded-xl p-5 space-y-3">
            <p className="text-sm font-medium text-neutral-800">Reset password</p>
            {!pendingReset ? (
              <>
                <div>
                  <label className="text-xs text-neutral-500 mb-1 block">Employee ID</label>
                  <input
                    value={forgotId}
                    onChange={(e) => setForgotId(e.target.value)}
                    placeholder="e.g. OGC111"
                    className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100"
                  />
                </div>
                {forgotError && <p className="text-xs text-red-600">{forgotError}</p>}
                <button onClick={handleRequestReset} className="w-full bg-emerald-700 text-white text-sm font-medium py-2.5 rounded-lg hover:bg-emerald-800">
                  Send reset code
                </button>
              </>
            ) : (
              <>
                <p className="text-xs text-neutral-500">
                  A reset code was sent to <span className="font-medium text-neutral-700">{pendingReset.user.email}</span>. This demo also opened your email client with it, and shows it below since there's no live mail server here.
                </p>
                <div className="bg-amber-50 text-amber-700 text-xs rounded-lg px-3 py-2 font-mono tracking-widest text-center">
                  {pendingReset.code} <span className="font-sans text-[10px] text-amber-500">(demo only)</span>
                </div>
                <div>
                  <label className="text-xs text-neutral-500 mb-1 block">Reset code</label>
                  <input
                    value={resetCode}
                    onChange={(e) => setResetCode(e.target.value)}
                    placeholder="6-digit code"
                    className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100"
                  />
                </div>
                <div>
                  <label className="text-xs text-neutral-500 mb-1 block">New password</label>
                  <input
                    type="password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="At least 6 characters"
                    className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100"
                  />
                </div>
                {forgotError && <p className="text-xs text-red-600">{forgotError}</p>}
                <button onClick={handleConfirmReset} className="w-full bg-emerald-700 text-white text-sm font-medium py-2.5 rounded-lg hover:bg-emerald-800">
                  Set new password
                </button>
              </>
            )}
            <button onClick={() => setMode("login")} className="w-full text-xs text-neutral-500 hover:text-neutral-700 text-center pt-1">
              Back to sign in
            </button>
          </div>
        )}

        {mode === "forgot" && resetDone && (
          <div className="bg-white border border-neutral-200 rounded-xl p-5 space-y-3 text-center">
            <div className="w-10 h-10 rounded-full bg-emerald-50 flex items-center justify-center mx-auto">
              <Check size={18} className="text-emerald-700" />
            </div>
            <p className="text-sm font-medium text-neutral-800">Password updated</p>
            <p className="text-xs text-neutral-500">You can now sign in with your new password.</p>
            <button onClick={() => { setMode("login"); setEmployeeId(pendingReset.user.employeeId); setPassword(""); }} className="w-full bg-emerald-700 text-white text-sm font-medium py-2.5 rounded-lg hover:bg-emerald-800">
              Back to sign in
            </button>
          </div>
        )}

        <p className="text-[11px] text-neutral-400 text-center mt-4">
          Demo login — in production, passwords are hashed and reset emails send from a real mail server.
        </p>
      </div>
    </div>
  );
}

