export default function DMSDemo() {
  const [currentUser, setCurrentUser] = useState(null);
  const [userLoaded, setUserLoaded] = useState(false);
  const [users, setUsers] = useState([]);
  const [usersLoaded, setUsersLoaded] = useState(false);
  const [auditLog, setAuditLog] = useState([]);
  const [auditLoaded, setAuditLoaded] = useState(false);
  const [requests, setRequests] = useState(SEED);
  const [loaded, setLoaded] = useState(false);
  const [view, setView] = useState("dashboard");
  const [selectedId, setSelectedId] = useState(null);
  const [newRequestType, setNewRequestType] = useState("purchase");
  const [search, setSearch] = useState("");

  // Load the accounts "database". First run ever: no saved users yet, so hash
  // SEED_USERS's plaintext passwords into {salt, passwordHash} before using them.
  useEffect(() => {
    (async () => {
      try {
        const result = await localOnly.get("dms_demo_users");
        if (result && result.value) {
          setUsers(await migrateUsers(JSON.parse(result.value)));
        } else {
          setUsers(await buildSeedUsers());
        }
      } catch (e) {
        setUsers(await buildSeedUsers());
      } finally {
        setUsersLoaded(true);
      }
    })();
  }, []);

  // Persist any change to the accounts list (new users, deactivations, password resets).
  useEffect(() => {
    if (!usersLoaded) return;
    (async () => {
      try {
        await localOnly.set("dms_demo_users", JSON.stringify(users));
      } catch (e) {
        console.error("Storage save failed", e);
      }
    })();
  }, [users, usersLoaded]);

  // Load / persist the audit trail.
  useEffect(() => {
    (async () => {
      try {
        const result = await storage.get("dms_demo_audit");
        if (result && result.value) setAuditLog(JSON.parse(result.value));
      } catch (e) {
        // no audit log yet
      } finally {
        setAuditLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    if (!auditLoaded) return;
    (async () => {
      try {
        await storage.set("dms_demo_audit", JSON.stringify(auditLog));
      } catch (e) {
        console.error("Storage save failed", e);
      }
    })();
  }, [auditLog, auditLoaded]);

  useEffect(() => {
    (async () => {
      try {
        const result = await localOnly.get("dms_demo_user");
        if (result && result.value) {
          setCurrentUser(JSON.parse(result.value));
        }
      } catch (e) {
        // no saved login yet
      } finally {
        setUserLoaded(true);
      }
    })();
  }, []);

  // Keep the logged-in session in sync with the accounts list: if an admin deactivates
  // the currently logged-in account, or edits it, reflect that immediately rather than
  // trusting the stale copy that was cached at login time.
  useEffect(() => {
    if (!usersLoaded || !currentUser) return;
    const latest = users.find((u) => u.employeeId === currentUser.employeeId);
    if (!latest || !latest.active) {
      logout();
      return;
    }
    if (JSON.stringify(latest) !== JSON.stringify(currentUser)) {
      loginAs(latest);
    }
  }, [users, usersLoaded]);

  function pushAudit(action, target, details) {
    setAuditLog((prev) => [
      ...prev,
      {
        id: genId("aud"),
        timestamp: Date.now(),
        actor: currentUser ? `${currentUser.name} (${currentUser.employeeId})` : "System",
        action,
        target,
        details,
      },
    ]);
  }

  async function loginAs(user) {
    setCurrentUser(user);
    try {
      await localOnly.set("dms_demo_user", JSON.stringify(user));
    } catch (e) {
      console.error("Storage save failed", e);
    }
  }

  // The actual, user-initiated sign-in — records to the audit trail. loginAs()
  // alone is also used to silently rehydrate/refresh a session, which shouldn't audit.
  async function handleLoginSuccess(user) {
    await loginAs(user);
    setAuditLog((prev) => [
      ...prev,
      { id: genId("aud"), timestamp: Date.now(), actor: `${user.name} (${user.employeeId})`, action: "login", target: user.employeeId, details: "" },
    ]);
  }

  async function logout() {
    if (currentUser) {
      const name = `${currentUser.name} (${currentUser.employeeId})`;
      setAuditLog((prev) => [
        ...prev,
        { id: genId("aud"), timestamp: Date.now(), actor: name, action: "logout", target: currentUser.employeeId, details: "" },
      ]);
    }
    setCurrentUser(null);
    setView("dashboard");
    try {
      await localOnly.delete("dms_demo_user");
    } catch (e) {
      // ignore
    }
  }

  // Both take a plaintext password (typed by the user, or freshly generated) and
  // store only its salted hash — see the hashing note above buildSeedUsers().
  async function resetPassword(employeeId, newPlainPassword) {
    const salt = genSalt();
    const passwordHash = await hashPassword(newPlainPassword, salt);
    setUsers((prev) => prev.map((u) => (u.employeeId === employeeId ? { ...u, salt, passwordHash } : u)));
  }

  async function addUser(newUserWithPlainPassword) {
    const { password, ...rest } = newUserWithPlainPassword;
    const salt = genSalt();
    const passwordHash = await hashPassword(password, salt);
    setUsers((prev) => [...prev, { ...rest, salt, passwordHash }]);
  }

  function updateUser(employeeId, patch) {
    setUsers((prev) => prev.map((u) => (u.employeeId === employeeId ? { ...u, ...patch } : u)));
  }

  useEffect(() => {
    (async () => {
      try {
        const result = await storage.get("dms_demo_requests");
        if (result && result.value) {
          setRequests(JSON.parse(result.value));
        }
      } catch (e) {
        // no saved data yet, keep seed
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    (async () => {
      try {
        await storage.set("dms_demo_requests", JSON.stringify(requests));
      } catch (e) {
        console.error("Storage save failed", e);
      }
    })();
  }, [requests, loaded]);

  function addRequest(newReq) {
    setRequests((prev) => [newReq, ...prev]);
    setView("documents");
  }

  function updateRequest(id, patch) {
    setRequests((prev) => prev.map((r) => (r.id === id ? { ...r, ...patch } : r)));
  }

  function deleteRequest(id) {
    setRequests((prev) => prev.filter((r) => r.id !== id));
    setSelectedId(null);
    setView("documents");
  }

  // Scope what each logged-in role can see: IT only sees its own department's requests,
  // the approver sees everything awaiting/handled across departments.
  const scopedRequests =
    currentUser && currentUser.role === "requester"
      ? requests.filter((r) => r.department === currentUser.department)
      : requests;

  const filtered = scopedRequests.filter((r) => {
    const q = search.toLowerCase();
    return (
      r.item.toLowerCase().includes(q) ||
      r.department.toLowerCase().includes(q) ||
      r.vendors.some((v) => v.name.toLowerCase().includes(q))
    );
  });

  const stats = {
    total: scopedRequests.length,
    pending: scopedRequests.filter((r) => r.status === "pending").length,
    approved: scopedRequests.filter((r) => r.status === "approved" || r.status === "paid").length,
    totalValue: scopedRequests.reduce((sum, r) => {
      const v = r.vendors.find((v) => v.name === r.selectedVendor);
      return sum + Number((v && v.price) || 0);
    }, 0),
  };

  const selected = requests.find((r) => r.id === selectedId);

  if (!userLoaded || !usersLoaded || !auditLoaded) {
    return <div className="w-full h-screen bg-neutral-50" />;
  }

  if (!currentUser) {
    return <LoginScreen users={users} onLoginSuccess={handleLoginSuccess} onResetPassword={resetPassword} />;
  }

  const navItems = [
    { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
    ...(currentUser.role === "requester" ? [{ id: "new", label: "New request", icon: FilePlus2 }] : []),
    { id: "documents", label: currentUser.role === "approver" ? "Approvals" : currentUser.role === "accounts" ? "Payments" : "Documents", icon: FolderOpen },
    { id: "templates", label: "Templates", icon: LayoutTemplate },
    ...(currentUser.role === "admin" ? [{ id: "users", label: "Users", icon: Users }] : []),
    ...(currentUser.role === "admin" || currentUser.role === "approver" ? [{ id: "audit", label: "Audit trail", icon: History }] : []),
  ];

  return (
    <div className="w-full h-screen bg-neutral-50 flex overflow-hidden" style={{ fontFamily: "system-ui, -apple-system, sans-serif" }}>
      {/* Sidebar */}
      <div className="w-56 shrink-0 bg-white border-r border-neutral-200 flex flex-col h-full">
        <div className="px-5 py-5 border-b border-neutral-200 shrink-0">
          <img src={OLEEVIA_LOGO} alt="Oleevia" className="h-8 w-auto" />
          <p className="text-[11px] text-neutral-400 mt-2">DocFlow · Demo, not connected to real data</p>
        </div>
        <nav className="flex-1 px-3 py-4 space-y-1 overflow-y-auto">
          {navItems.map((item) => {
            const Icon = item.icon;
            const active = view === item.id || (view === "detail" && item.id === "documents");
            return (
              <button
                key={item.id}
                onClick={() => { setView(item.id); setSelectedId(null); if (item.id === "new") setNewRequestType("purchase"); }}
                className={`w-full flex items-center gap-2.5 px-3 py-2 rounded-lg text-sm transition-colors ${
                  active ? "bg-emerald-50 text-emerald-800 font-medium" : "text-neutral-600 hover:bg-neutral-50"
                }`}
              >
                <Icon size={16} />
                {item.label}
              </button>
            );
          })}
        </nav>
        <div className="px-5 py-3 border-t border-neutral-100 shrink-0">
          <p className="text-[10px] text-neutral-300">Oleevia DocFlow · Demo build</p>
        </div>
      </div>

      {/* Main column: header + scrollable content, both filling remaining width */}
      <div className="flex-1 min-w-0 h-full flex flex-col">
        {/* Header */}
        <div className="h-16 shrink-0 border-b border-neutral-200 bg-white flex items-center justify-between px-6">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold text-neutral-800 truncate">{PAGE_TITLES[view] || "Oleevia DocFlow"}</h2>
            <p className="text-[11px] text-neutral-400">
              Signed in as {currentUser.name} · {ROLE_LABELS[currentUser.role] || currentUser.role}
            </p>
          </div>
          <ProfileMenu
            currentUser={currentUser}
            onNavigate={(target) => { setView(target); setSelectedId(null); }}
            onLogout={logout}
          />
        </div>

        {/* Scrollable content */}
        <div className="flex-1 min-w-0 overflow-y-auto">
          {view === "dashboard" && (
            <Dashboard stats={stats} requests={scopedRequests} currentUser={currentUser} onOpen={(id) => { setSelectedId(id); setView("detail"); }} onNew={() => { setNewRequestType("purchase"); setView("new"); }} />
          )}
          {view === "new" && currentUser.role === "requester" && (
            <NewRequestForm currentUser={currentUser} initialType={newRequestType} onSubmit={addRequest} onCancel={() => setView("documents")} onAudit={pushAudit} />
          )}
          {view === "documents" && (
            <DocumentsList
              requests={filtered}
              search={search}
              setSearch={setSearch}
              currentUser={currentUser}
              onOpen={(id) => { setSelectedId(id); setView("detail"); }}
              onNew={() => { setNewRequestType("purchase"); setView("new"); }}
            />
          )}
          {view === "templates" && <TemplatesPage onUse={(type) => { setNewRequestType(type); setView("new"); }} />}
          {view === "users" && currentUser.role === "admin" && (
            <UserManagement users={users} currentUser={currentUser} onAdd={addUser} onUpdate={updateUser} onResetPassword={resetPassword} onAudit={pushAudit} />
          )}
          {view === "audit" && (currentUser.role === "admin" || currentUser.role === "approver") && (
            <AuditTrail auditLog={auditLog} />
          )}
          {view === "profile" && (
            <ProfilePage currentUser={currentUser} onNavigate={(target) => { setView(target); setSelectedId(null); }} />
          )}
          {view === "changepw" && (
            <ChangePasswordPage currentUser={currentUser} onChangePassword={resetPassword} onAudit={pushAudit} />
          )}
          {view === "detail" && selected && (
            <RequestDetail
              request={selected}
              currentUser={currentUser}
              onBack={() => setView("documents")}
              onUpdate={(patch) => updateRequest(selected.id, patch)}
              onDelete={() => deleteRequest(selected.id)}
              onAudit={pushAudit}
              auditLog={auditLog}
            />
          )}
        </div>
      </div>
    </div>
  );
}

function Dashboard({ stats, requests, currentUser, onOpen, onNew }) {
  const recent = [...requests].sort((a, b) => b.createdAt - a.createdAt).slice(0, 5);
  return (
    <div className="p-8 max-w-5xl mx-auto w-full">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-xl font-semibold text-neutral-900">Dashboard</h1>
          <p className="text-sm text-neutral-500 mt-0.5">
            {currentUser.role === "approver"
              ? "Purchase requests awaiting your review, across departments."
              : currentUser.role === "accounts"
              ? "Requests approved and awaiting fund release, plus what's still pending approval."
              : "Your department's purchase requests and their status."}
          </p>
        </div>
        {currentUser.role === "requester" && (
          <button onClick={onNew} className="flex items-center gap-1.5 bg-emerald-700 text-white text-sm font-medium px-3.5 py-2 rounded-lg hover:bg-emerald-800">
            <FilePlus2 size={15} /> New request
          </button>
        )}
      </div>

      <div className="grid grid-cols-4 gap-3 mb-8">
        <StatCard label="Total requests" value={stats.total} />
        <StatCard label="Pending approval" value={stats.pending} highlight="amber" />
        <StatCard label="Approved" value={stats.approved} highlight="emerald" />
        <StatCard label="Approved value" value={formatINR(stats.totalValue)} />
      </div>

      <div className="bg-white border border-neutral-200 rounded-xl overflow-hidden">
        <div className="px-5 py-3 border-b border-neutral-200">
          <h2 className="text-sm font-medium text-neutral-800">Recent activity</h2>
        </div>
        <div>
          {recent.map((r) => {
            const typeInfo = REQUEST_TYPES[r.requestType || "purchase"];
            return (
            <button
              key={r.id}
              onClick={() => onOpen(r.id)}
              className="w-full flex items-center justify-between px-5 py-3 border-b last:border-b-0 border-neutral-100 hover:bg-neutral-50 text-left"
            >
              <div className="min-w-0">
                <p className="text-sm text-neutral-800 truncate">{r.item}</p>
                <p className="text-xs text-neutral-400 mt-0.5 flex items-center gap-1.5">
                  <span className="inline-flex items-center gap-1 text-neutral-500 bg-neutral-100 rounded-full px-1.5 py-0.5 text-[10px]">
                    <typeInfo.icon size={10} /> {typeInfo.shortLabel}
                  </span>
                  {r.department} · {new Date(r.createdAt).toLocaleDateString("en-IN")}
                </p>
              </div>
              <div className="flex items-center gap-3 shrink-0">
                <StatusBadge status={r.status} />
                <ChevronRight size={16} className="text-neutral-300" />
              </div>
            </button>
            );
          })}
          {recent.length === 0 && <p className="px-5 py-6 text-sm text-neutral-400">No requests yet.</p>}
        </div>
      </div>
    </div>
  );
}

function StatCard({ label, value, highlight }) {
  const color = highlight === "amber" ? "text-amber-700" : highlight === "emerald" ? "text-emerald-700" : "text-neutral-900";
  return (
    <div className="bg-white border border-neutral-200 rounded-xl p-4">
      <p className="text-xs text-neutral-500">{label}</p>
      <p className={`text-2xl font-semibold mt-1 ${color}`}>{value}</p>
    </div>
  );
}

function TemplatesPage({ onUse }) {
  const templates = [
    { type: "purchase", name: REQUEST_TYPES.purchase.label, desc: REQUEST_TYPES.purchase.desc, fields: 7, icon: REQUEST_TYPES.purchase.icon, active: true },
    { type: "renewal", name: REQUEST_TYPES.renewal.label, desc: REQUEST_TYPES.renewal.desc, fields: 6, icon: REQUEST_TYPES.renewal.icon, active: true },
    { type: "travel", name: REQUEST_TYPES.travel.label, desc: REQUEST_TYPES.travel.desc, fields: 8, icon: REQUEST_TYPES.travel.icon, active: true },
    { type: "ceo", name: REQUEST_TYPES.ceo.label, desc: REQUEST_TYPES.ceo.desc, fields: 4, icon: REQUEST_TYPES.ceo.icon, active: true },
  ];
  return (
    <div className="p-8 max-w-5xl mx-auto w-full">
      <h1 className="text-xl font-semibold text-neutral-900 mb-1">Templates</h1>
      <p className="text-sm text-neutral-500 mb-6">Structured field sets used to generate documents automatically.</p>
      <div className="grid grid-cols-2 gap-4">
        {templates.map((t) => (
          <div key={t.name} className="bg-white border border-neutral-200 rounded-xl p-4 flex flex-col">
            <div className="w-8 h-8 rounded-lg bg-emerald-50 flex items-center justify-center mb-3">
              <t.icon size={16} className="text-emerald-700" />
            </div>
            <p className="text-sm font-medium text-neutral-900">{t.name}</p>
            <p className="text-xs text-neutral-500 mt-1 flex-1">{t.desc}</p>
            <p className="text-[11px] text-neutral-400 mt-3">{t.fields} fields</p>
            <button
              onClick={t.active ? () => onUse(t.type) : undefined}
              disabled={!t.active}
              className={`mt-3 text-xs font-medium px-3 py-2 rounded-lg border ${
                t.active
                  ? "border-emerald-700 text-emerald-700 hover:bg-emerald-50"
                  : "border-neutral-200 text-neutral-300 cursor-not-allowed"
              }`}
            >
              {t.active ? "Use template" : "Coming in this demo"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// --- Attachments: pick/upload a file, or open one that was already stored ---
function AttachmentPicker({ value, onChange, label = "file" }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  async function handleFile(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = ""; // allow re-selecting the same file later
    if (!file) return;
    if (file.size > MAX_ATTACHMENT_BYTES) {
      setError(`File is too large (max ${(MAX_ATTACHMENT_BYTES / (1024 * 1024)).toFixed(0)}MB).`);
      return;
    }
    setBusy(true);
    setError("");
    try {
      const dataUrl = await readFileAsDataURL(file);
      const key = genId("att");
      await storage.set(key, JSON.stringify({ name: file.name, type: file.type, size: file.size, dataUrl }));
      onChange({ key, name: file.name, type: file.type, size: file.size });
    } catch (err) {
      console.error(err);
      setError("Couldn't attach that file. Try again.");
    } finally {
      setBusy(false);
    }
  }

  async function handleRemove() {
    if (value && value.key) {
      try { await storage.delete(value.key); } catch (e) { /* ignore */ }
    }
    onChange(null);
  }

  if (value) {
    return (
      <div className="flex items-center justify-between gap-2 px-3 py-2 border border-neutral-200 rounded-lg bg-neutral-50 text-xs">
        <span className="truncate text-neutral-700 flex items-center gap-1.5">
          <Paperclip size={12} className="text-neutral-400 shrink-0" />
          {value.name} · {formatBytes(value.size)}
        </span>
        <button type="button" onClick={handleRemove} className="text-neutral-400 hover:text-red-600 shrink-0">
          <X size={13} />
        </button>
      </div>
    );
  }

  return (
    <div>
      <label className={`flex items-center gap-1.5 px-3 py-2 text-xs border border-dashed border-neutral-300 rounded-lg cursor-pointer hover:bg-neutral-50 text-neutral-500 ${busy ? "opacity-50 pointer-events-none" : ""}`}>
        <Paperclip size={13} className="text-neutral-400" />
        {busy ? "Uploading…" : `Attach ${label}`}
        <input type="file" className="hidden" onChange={handleFile} />
      </label>
      {error && <p className="text-[11px] text-red-600 mt-1">{error}</p>}
    </div>
  );
}

function AttachmentLink({ meta }) {
  const [loading, setLoading] = useState(false);
  async function handleOpen() {
    setLoading(true);
    try {
      const result = await storage.get(meta.key);
      if (!result) throw new Error("not found");
      const data = JSON.parse(result.value);
      const a = document.createElement("a");
      a.href = data.dataUrl;
      a.download = data.name;
      a.click();
    } catch (e) {
      alert("Couldn't load this attachment.");
    } finally {
      setLoading(false);
    }
  }
  return (
    <button type="button" onClick={handleOpen} disabled={loading} className="flex items-center gap-1 text-xs text-emerald-700 hover:underline disabled:opacity-50">
      <Paperclip size={12} /> {loading ? "Opening…" : meta.name}
    </button>
  );
}

// --- Audit trail --------------------------------------------------------
const AUDIT_ACTION_LABELS = {
  login: "Signed in",
  logout: "Signed out",
  request_created: "Request submitted",
  request_approved: "Request approved",
  request_rejected: "Request rejected",
  fund_released: "Fund released",
  user_created: "User created",
  user_deactivated: "User deactivated",
  user_reactivated: "User reactivated",
  password_reset: "Password reset",
};

function AuditTrail({ auditLog }) {
  const [search, setSearch] = useState("");
  const q = search.toLowerCase();
  const rows = [...auditLog]
    .sort((a, b) => b.timestamp - a.timestamp)
    .filter(
      (e) =>
        !q ||
        e.actor.toLowerCase().includes(q) ||
        (e.details || "").toLowerCase().includes(q) ||
        (AUDIT_ACTION_LABELS[e.action] || e.action).toLowerCase().includes(q)
    );

  return (
    <div className="p-8 max-w-5xl mx-auto w-full">
      <h1 className="text-xl font-semibold text-neutral-900 mb-1">Audit trail</h1>
      <p className="text-sm text-neutral-500 mb-6">Every login, approval decision, and account change, in order.</p>
      <div className="relative mb-4">
        <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400" />
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search by person, action, or detail"
          className="w-full pl-9 pr-3 py-2 text-sm border border-neutral-200 rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-emerald-100 focus:border-emerald-400"
        />
      </div>
      <div className="bg-white border border-neutral-200 rounded-xl overflow-hidden">
        {rows.map((e) => (
          <div key={e.id} className="px-4 py-3 border-b last:border-b-0 border-neutral-100 text-sm">
            <div className="flex items-center justify-between gap-3">
              <span className="font-medium text-neutral-800">{AUDIT_ACTION_LABELS[e.action] || e.action}</span>
              <span className="text-[11px] text-neutral-400 shrink-0">{new Date(e.timestamp).toLocaleString("en-IN")}</span>
            </div>
            <p className="text-xs text-neutral-500 mt-0.5">
              {e.actor}
              {e.details ? ` — ${e.details}` : ""}
            </p>
          </div>
        ))}
        {rows.length === 0 && <p className="px-5 py-6 text-sm text-neutral-400">No activity recorded yet.</p>}
      </div>
    </div>
  );
}

const ROLE_LABELS = { admin: "Admin", requester: "Requester", approver: "Approver", accounts: "Accounts" };

function UserManagement({ users, currentUser, onAdd, onUpdate, onResetPassword, onAudit }) {
  const [showForm, setShowForm] = useState(false);
  const [employeeId, setEmployeeId] = useState("");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("requester");
  const [department, setDepartment] = useState(DEPARTMENTS[0]);
  const [error, setError] = useState("");
  const [lastCreated, setLastCreated] = useState(null); // { user, tempPassword }
  const [lastReset, setLastReset] = useState(null); // { employeeId, tempPassword }

  function resetForm() {
    setEmployeeId(""); setName(""); setEmail(""); setRole("requester"); setDepartment(DEPARTMENTS[0]); setError("");
  }

  function handleAdd() {
    const id = employeeId.trim();
    if (!id || !name.trim() || !email.trim()) { setError("Employee ID, name, and email are required."); return; }
    if (users.some((u) => u.employeeId.toLowerCase() === id.toLowerCase())) {
      setError("That employee ID already exists.");
      return;
    }
    const tempPassword = genTempPassword();
    const newUser = {
      employeeId: id,
      name: name.trim(),
      email: email.trim(),
      role,
      department: role === "requester" ? department : null,
      password: tempPassword,
      active: true,
    };
    onAdd(newUser);
    onAudit("user_created", id, `Created account for ${newUser.name} (${ROLE_LABELS[role] || role})`);
    setLastCreated({ user: newUser, tempPassword });
    setLastReset(null);
    setShowForm(false);
    resetForm();
  }

  function handleToggleActive(u) {
    onUpdate(u.employeeId, { active: !u.active });
    onAudit(u.active ? "user_deactivated" : "user_reactivated", u.employeeId, `${u.name}'s account`);
  }

  function handleResetPassword(u) {
    const tempPassword = genTempPassword();
    onResetPassword(u.employeeId, tempPassword);
    onAudit("password_reset", u.employeeId, `Password reset for ${u.name} by admin`);
    setLastReset({ employeeId: u.employeeId, tempPassword });
    setLastCreated(null);
    window.open(
      buildMailto(
        u.email,
        "Your Oleevia DocFlow password has been reset",
        `Hello ${u.name},\n\nYour password was reset by an administrator.\n\nTemporary password: ${tempPassword}\n\nPlease sign in and change it as soon as possible.`
      ),
      "_blank"
    );
  }

  return (
    <div className="p-8 max-w-5xl mx-auto w-full">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-xl font-semibold text-neutral-900">Users</h1>
          <p className="text-sm text-neutral-500 mt-0.5">Add accounts, deactivate access, and reset passwords.</p>
        </div>
        <button
          onClick={() => { setShowForm((s) => !s); setError(""); }}
          className="flex items-center gap-1.5 bg-emerald-700 text-white text-sm font-medium px-3.5 py-2 rounded-lg hover:bg-emerald-800"
        >
          <UserPlus size={15} /> New user
        </button>
      </div>

      {showForm && (
        <div className="bg-white border border-neutral-200 rounded-xl p-5 mb-5">
          <div className="grid grid-cols-2 gap-4 mb-4">
            <div>
              <label className="text-xs text-neutral-500 mb-1 block">Employee ID</label>
              <input value={employeeId} onChange={(e) => setEmployeeId(e.target.value)} placeholder="e.g. OGC114"
                className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100" />
            </div>
            <div>
              <label className="text-xs text-neutral-500 mb-1 block">Full name</label>
              <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Full name"
                className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100" />
            </div>
            <div>
              <label className="text-xs text-neutral-500 mb-1 block">Email</label>
              <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@company.com"
                className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100" />
            </div>
            <div>
              <label className="text-xs text-neutral-500 mb-1 block">Role</label>
              <select value={role} onChange={(e) => setRole(e.target.value)}
                className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100 bg-white">
                <option value="requester">Requester (department)</option>
                <option value="approver">Approver</option>
                <option value="accounts">Accounts</option>
                <option value="admin">Admin</option>
              </select>
            </div>
            {role === "requester" && (
              <div>
                <label className="text-xs text-neutral-500 mb-1 block">Department</label>
                <select value={department} onChange={(e) => setDepartment(e.target.value)}
                  className="w-full px-3 py-2 text-sm border border-neutral-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-emerald-100 bg-white">
                  {DEPARTMENTS.map((d) => <option key={d} value={d}>{d}</option>)}
                </select>
              </div>
            )}
          </div>
          {error && <p className="text-xs text-red-600 mb-3">{error}</p>}
          <div className="flex justify-end gap-2">
            <button onClick={() => { setShowForm(false); resetForm(); }} className="text-sm px-3.5 py-2 rounded-lg border border-neutral-200 text-neutral-600 hover:bg-neutral-50">
              Cancel
            </button>
            <button onClick={handleAdd} className="text-sm font-medium px-3.5 py-2 rounded-lg bg-emerald-700 text-white hover:bg-emerald-800">
              Create account
            </button>
          </div>
        </div>
      )}

      {lastCreated && (
        <div className="bg-emerald-50 border border-emerald-100 rounded-lg px-4 py-3 mb-5 text-xs text-emerald-800">
          Account created for <strong>{lastCreated.user.name}</strong> ({lastCreated.user.employeeId}). Temporary password:{" "}
          <span className="font-mono tracking-wide">{lastCreated.tempPassword}</span> — share this securely; it won't be shown again.
        </div>
      )}
      {lastReset && (
        <div className="bg-amber-50 border border-amber-100 rounded-lg px-4 py-3 mb-5 text-xs text-amber-800">
          Password reset for <strong>{lastReset.employeeId}</strong>. Temporary password:{" "}
          <span className="font-mono tracking-wide">{lastReset.tempPassword}</span> — an email draft was opened for you to send it.
        </div>
      )}

      <div className="bg-white border border-neutral-200 rounded-xl overflow-hidden">
        <div className="grid grid-cols-6 bg-neutral-50 text-[11px] font-medium text-neutral-500 px-4 py-2.5">
          <span className="col-span-2">Name / Employee ID</span>
          <span>Role</span>
          <span>Department</span>
          <span>Status</span>
          <span className="text-right">Actions</span>
        </div>
        {users.map((u) => (
          <div key={u.employeeId} className="grid grid-cols-6 items-center px-4 py-3 border-t border-neutral-100 text-sm">
            <div className="col-span-2 min-w-0">
              <p className="text-neutral-800 truncate">{u.name}</p>
              <p className="text-[11px] text-neutral-400">{u.employeeId} · {u.email}</p>
            </div>
            <span className="text-neutral-600 text-xs">{ROLE_LABELS[u.role] || u.role}</span>
            <span className="text-neutral-600 text-xs">{u.department || "—"}</span>
            <span className={`text-xs font-medium ${u.active ? "text-emerald-700" : "text-neutral-400"}`}>
              {u.active ? "Active" : "Deactivated"}
            </span>
            <div className="flex justify-end gap-1.5">
              <button
                title="Reset password"
                onClick={() => handleResetPassword(u)}
                className="p-1.5 rounded-md text-neutral-400 hover:text-emerald-700 hover:bg-emerald-50"
              >
                <KeyRound size={14} />
              </button>
              <button
                title={u.active ? "Deactivate" : "Reactivate"}
                onClick={() => handleToggleActive(u)}
                disabled={u.employeeId === currentUser.employeeId}
                className={`p-1.5 rounded-md ${
                  u.employeeId === currentUser.employeeId
                    ? "text-neutral-200 cursor-not-allowed"
                    : "text-neutral-400 hover:text-red-600 hover:bg-red-50"
                }`}
              >
                <Power size={14} />
              </button>
            </div>
          </div>
        ))}
      </div>
      <p className="text-[11px] text-neutral-400 mt-2">
        You can't deactivate the account you're currently signed in with.
      </p>
    </div>
  );
}

